<?php $pageTitle='Appointment'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Administrator SIMRS']);$msg='';$error='';$patients=$pdo->query("SELECT id,medical_record_no,name FROM patients ORDER BY name")->fetchAll();$clinics=$pdo->query("SELECT * FROM master_clinics WHERE active=1 ORDER BY name")->fetchAll();$doctors=$pdo->query("SELECT md.*,mc.name clinic_name FROM master_doctors md LEFT JOIN master_clinics mc ON mc.id=md.clinic_id WHERE md.active=1 ORDER BY md.name")->fetchAll();
if(isset($_POST['save'])){try{$pid=(int)$_POST['patient_id'];$cid=(int)$_POST['clinic_id'];$doctor=trim($_POST['doctor']);$date=$_POST['date']??'';$time=$_POST['time']??'';if(!$pid||!$cid||!$doctor||!$date||!$time)throw new RuntimeException('Pasien, unit, dokter, tanggal, dan waktu wajib diisi.');if($date<date('Y-m-d'))throw new RuntimeException('Tanggal appointment tidak boleh sebelum hari ini.');$p=$pdo->prepare('SELECT * FROM patients WHERE id=?');$p->execute([$pid]);$patient=$p->fetch();$c=$pdo->prepare('SELECT * FROM master_clinics WHERE id=?');$c->execute([$cid]);$clinic=$c->fetch();if(!$patient||!$clinic)throw new RuntimeException('Data pasien atau unit layanan tidak tersedia.');$dup=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE doctor=? AND appointment_date=? AND appointment_time=? AND status IN ('confirmed','pending')");$dup->execute([$doctor,$date,$time]);if((int)$dup->fetchColumn()>0)throw new RuntimeException('Jadwal dokter pada tanggal dan waktu tersebut sudah terisi.');$no='APT-'.date('ymd',strtotime($date)).'-'.str_pad((string)random_int(1,999),3,'0',STR_PAD_LEFT);$pdo->prepare("INSERT INTO appointments(patient_id,clinic_id,clinic,doctor,appointment_date,appointment_time,appointment_no,status,reminder_status) VALUES(?,?,?,?,?,?,?,'confirmed','Terkirim')")->execute([$pid,$cid,$clinic['name'],$doctor,$date,$time,$no]);$id=(int)$pdo->lastInsertId();audit($pdo,'CREATE_APPOINTMENT','appointments',$id,'Appointment '.$no.' untuk '.$patient['medical_record_no']);$msg='Appointment tersimpan dengan nomor '.$no.'.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query("SELECT a.*,p.name,p.medical_record_no FROM appointments a JOIN patients p ON p.id=a.patient_id WHERE a.appointment_date>=CURDATE() ORDER BY a.appointment_date,a.appointment_time LIMIT 20")->fetchAll();include 'partials/header.php'; ?>
<?php if($msg): ?><div class="alert">✓ <?=e($msg)?></div><?php endif; ?><?php if($error): ?><div class="alert error">⚠ <?=e($error)?></div><?php endif; ?>
<div class="grid"><div class="s-5"><div class="card"><div class="card-title"><div><h2>Jadwalkan appointment</h2><p>Pendaftaran kunjungan terencana sebelum hari pelayanan.</p></div></div><form method="post"><label>Pasien</label><select name="patient_id" required><option value="">Pilih pasien</option><?php foreach($patients as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> • <?=e($p['medical_record_no'])?></option><?php endforeach; ?></select><label>Unit layanan</label><select name="clinic_id" required><option value="">Pilih unit</option><?php foreach($clinics as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select><label>Dokter</label><select name="doctor" required><option value="">Pilih dokter</option><?php foreach($doctors as $d): ?><option value="<?=e($d['name'])?>"><?=e($d['name'])?> • <?=e($d['clinic_name'])?></option><?php endforeach; ?></select><div class="form-grid"><div><label>Tanggal</label><input type="date" name="date" min="<?=date('Y-m-d')?>" required></div><div><label>Waktu</label><input type="time" name="time" required></div></div><button class="btn" style="width:100%;margin-top:16px">Simpan Appointment</button></form></div><div class="card mt"><div class="eyebrow">KETERANGAN</div><h3 style="margin:5px 0">Nomor appointment</h3><div class="hint">Nomor appointment dibuat otomatis setelah jadwal tersimpan. Pasien tetap perlu melalui proses registrasi kunjungan pada hari pelayanan.</div></div></div><div class="s-7"><div class="card"><div class="card-title"><div><h2>Daftar appointment mendatang</h2><p>Jadwal yang telah tercatat dan menunggu hari pelayanan.</p></div></div><div class="table-wrap"><table><tr><th>Tanggal</th><th>Pasien</th><th>Unit</th><th>Dokter</th><th>No. Appointment</th><th>Status</th></tr><?php foreach($rows as $a): ?><tr><td><b><?=e(date('d/m/Y',strtotime($a['appointment_date'])))?></b><div class="muted"><?=e(substr($a['appointment_time'],0,5))?></div></td><td><b><?=e($a['name'])?></b><div class="muted"><?=e($a['medical_record_no'])?></div></td><td><?=e($a['clinic'])?></td><td><?=e($a['doctor'])?></td><td><?=e($a['appointment_no'])?></td><td><span class="badge <?=($a['status']==='confirmed'?'green':'amber')?>"><?=e($a['status']==='confirmed'?'Terjadwal':'Menunggu Konfirmasi')?></span></td></tr><?php endforeach; ?></table><?php if(!$rows): ?><div class="empty">Belum ada appointment yang terjadwal.</div><?php endif; ?></div></div></div></div>
<?php include 'partials/footer.php'; ?>
